    <div id="app"></div>
    <script>
      function createField(config) {
        var describedBy = [config.helpId, config.errorId].filter(Boolean).join(" ");

        return `
          <div class="form-field">
            <label class="field-label" for="${config.id}">
              <span>${config.label}</span>
              ${config.required ? '<span class="required-star" aria-hidden="true">*</span>' : ""}
            </label>
            <input
              class="field-control"
              id="${config.id}"
              name="${config.name}"
              type="${config.type}"
              ${config.required ? "required" : ""}
              autocomplete="${config.autocomplete}"
              placeholder="${config.placeholder}"
              aria-describedby="${describedBy}"
            />
            ${
              config.helpText
                ? '<p class="field-help" id="' + config.helpId + '">' + config.helpText + "</p>"
                : ""
            }
            <p class="field-error" id="${config.errorId}" hidden></p>
          </div>
        `;
      }

      function ContactForm() {
        return `
          <section class="contact-card" aria-labelledby="contact-heading">
            <h2 class="card-heading" id="contact-heading">Contact support</h2>
            <p class="card-subtitle">Tell us a little about your issue and our team will follow up.</p>
            <p class="required-note"><span class="required-star" aria-hidden="true">*</span> Required fields</p>
            <form id="support-form" class="form-stack" novalidate>
              <p class="status-banner" id="form-status" aria-live="polite"></p>
              ${createField({
                id: "full-name",
                name: "fullName",
                label: "Full name",
                type: "text",
                required: true,
                autocomplete: "name",
                placeholder: "Jordan Lee",
                errorId: "full-name-error"
              })}
              ${createField({
                id: "email-address",
                name: "emailAddress",
                label: "Email address",
                type: "email",
                required: true,
                autocomplete: "email",
                placeholder: "jordan@example.com",
                errorId: "email-address-error"
              })}
              ${createField({
                id: "phone-number",
                name: "phoneNumber",
                label: "Phone number (optional)",
                type: "tel",
                required: false,
                autocomplete: "tel",
                placeholder: "(555) 123-4567",
                helpId: "phone-number-help",
                helpText: "Use digits only or a format like (555) 123-4567.",
                errorId: "phone-number-error"
              })}
              <button class="button-primary" type="submit">Send request</button>
            </form>
            <div class="contact-meta">
              <div class="meta-card">
                <strong>Typical response</strong>
                <span>Within one business day</span>
              </div>
              <div class="meta-card">
                <strong>Coverage</strong>
                <span>Billing, account, and technical help</span>
              </div>
            </div>
          </section>
        `;
      }

      function SupportHero() {
        return `
          <section class="hero-copy" aria-labelledby="page-title">
            <p class="eyebrow">Support that feels personal</p>
            <h1 id="page-title">Get help from the Nova support team.</h1>
            <p>
              Reach out with your account or product questions and we'll route your request to the
              right specialist right away.
            </p>
            <ul class="feature-list" aria-label="Support highlights">
              <li>
                <span class="feature-icon" aria-hidden="true">1</span>
                <div>
                  <strong>Faster triage</strong>
                  <span>Required contact details help us reply without extra back and forth.</span>
                </div>
              </li>
              <li>
                <span class="feature-icon" aria-hidden="true">2</span>
                <div>
                  <strong>Human follow-up</strong>
                  <span>Optional phone details make it easy to call when an issue is urgent.</span>
                </div>
              </li>
              <li>
                <span class="feature-icon" aria-hidden="true">3</span>
                <div>
                  <strong>Clear next steps</strong>
                  <span>We confirm when your request is ready so you always know what happens next.</span>
                </div>
              </li>
            </ul>
          </section>
        `;
      }

      function Header() {
        return `
          <header class="site-header">
            <a class="brand" href="#" aria-label="Nova home">
              <span class="brand-mark" aria-hidden="true">N</span>
              <span>Nova</span>
            </a>
            <nav class="site-nav" aria-label="Primary">
              <a href="#support-form">Jump to form</a>
            </nav>
          </header>
        `;
      }

      function App() {
        return `
          <a href="#maincontent" class="skip-link">Skip to main content</a>
          <div class="site-shell">
            ${Header()}
            <main id="maincontent" tabindex="-1">
              <div class="hero-grid">
                ${SupportHero()}
                ${ContactForm()}
              </div>
            </main>
          </div>
        `;
      }

      document.getElementById("app").innerHTML = App();

      var form = document.getElementById("support-form");
      var statusElement = document.getElementById("form-status");

      var fieldRules = {
        "full-name": {
          errorElementId: "full-name-error",
          validate: function (value) {
            if (!value.trim()) {
              return "Error: Enter your full name.";
            }
            return "";
          }
        },
        "email-address": {
          errorElementId: "email-address-error",
          validate: function (value) {
            if (!value.trim()) {
              return "Error: Enter your email address.";
            }
            if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value.trim())) {
              return "Error: Enter a valid email address, such as name@example.com.";
            }
            return "";
          }
        },
        "phone-number": {
          errorElementId: "phone-number-error",
          validate: function (value) {
            if (!value.trim()) {
              return "";
            }
            if (!/^[+]?[\d()\-\s]{7,20}$/.test(value.trim())) {
              return "Error: Enter a phone number using digits and optional spaces, parentheses, or hyphens.";
            }
            return "";
          }
        }
      };

      function setStatus(message, tone) {
        statusElement.textContent = message;
        statusElement.className = "status-banner" + (tone ? " is-" + tone : "");
      }

      function validateField(field) {
        var rule = fieldRules[field.id];
        var errorElement = document.getElementById(rule.errorElementId);
        var message = rule.validate(field.value);
        var isValid = message === "";

        if (isValid) {
          field.removeAttribute("aria-invalid");
        } else {
          field.setAttribute("aria-invalid", "true");
        }
        errorElement.hidden = isValid;
        errorElement.textContent = message;

        return isValid;
      }

      function validateForm() {
        var fields = Object.keys(fieldRules).map(function (id) {
          return document.getElementById(id);
        });
        var firstInvalid = null;

        fields.forEach(function (field) {
          var isValid = validateField(field);
          if (!isValid && !firstInvalid) {
            firstInvalid = field;
          }
        });

        if (firstInvalid) {
          setStatus("Please correct the highlighted fields and try again.", "error");
          firstInvalid.focus();
          return false;
        }

        setStatus("Thanks. Your support request has been captured.", "success");
        return true;
      }

      form.addEventListener("submit", function (event) {
        event.preventDefault();
        if (validateForm()) {
          form.reset();
          Object.keys(fieldRules).forEach(function (id) {
            var field = document.getElementById(id);
            var errorElement = document.getElementById(fieldRules[id].errorElementId);
            field.removeAttribute("aria-invalid");
            errorElement.hidden = true;
            errorElement.textContent = "";
          });
        }
      });

      form.addEventListener("blur", function (event) {
        if (fieldRules[event.target.id]) {
          validateField(event.target);
        }
      }, true);

      form.addEventListener("input", function (event) {
        if (fieldRules[event.target.id] && event.target.getAttribute("aria-invalid") === "true") {
          validateField(event.target);
        }
      });
    </script>
  </body>
</html>
